/* From Uiverse.io by Mhyar-nsi - Tags: blue, button, hover, ring */
.__UIV_SCOPE__ button {
  font-family: monospace;
  background-color: #f3f7fe;
  color: #3b82f6;
  border: none;
  border-radius: 8px;
  width: 100px;
  height: 45px;
  transition: .3s;
}

.__UIV_SCOPE__ button:hover {
  background-color: #3b82f6;
  box-shadow: 0 0 0 5px #3b83f65f;
  color: #fff;
}
